UPDATE review_reactions
SET reaction_type = #{reactionType}
WHERE reaction_id = #{reactionId}

mapper.select:
SELECT review_id AS reviewId, SUM(CASE WHEN reaction_type = 'LIKE' THEN 1 ELSE 0 END) AS likeCount, SUM(CASE WHEN reaction_type = 'DISLIKE' THEN 1 ELSE 0 END) AS dislikeCount FROM review_reactions WHERE review_id IN
#{reviewId}
GROUP BY review_id
